129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        List<String> missingFields = new ArrayList<>();
133	        if (isBlank(ownerFieldsDto.getFirstName())) {
134	            missingFields.add("firstName");
135	        }
136	        if (isBlank(ownerFieldsDto.getLastName())) {
137	            missingFields.add("lastName");
138	        }
139	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
140	        if (isBlank(normalizedAddress)) {
141	            missingFields.add("address");
142	        }
143	        if (isBlank(ownerFieldsDto.getCity())) {
144	            missingFields.add("city");
145	        }
146	        if (isBlank(ownerFieldsDto.getTelephone())) {
147	            missingFields.add("telephone");
148	        }
149	        if (!missingFields.isEmpty()) {
150	            throw new MissingOwnerFieldsException(missingFields);
151	        }
152	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
153	        LocalDate registrationDate = toBusinessDay(
154	            ownerFieldsDto.getRegistrationDate() != null
155	                ? ownerFieldsDto.getRegistrationDate()
156	                : LocalDate.now());
157	        long registeredOnDay = this.clinicService.findAllOwners().stream()
158	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
159	            .count();
160	        if (registeredOnDay >= 100) {
161	            throw new DailyRegistrationLimitException(
162	                "100 or more owners have already been registered today");
163	        }
164	        boolean bulkSignupWarning = registeredOnDay > 80;
165	        String city = ownerFieldsDto.getCity();
166	        long ownersInCity = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
168	            .count();
169	        if (ownersInCity >= 50) {
170	            throw new CityAtCapacityException(
171	                "the owner's city already contains 50 or more owners");
172	        }
173	        ownerFieldsDto.setAddress(normalizedAddress);
174	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
175	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
177	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
178	            .toList();
179	        String householdId = null;
180	        if (!householdMembers.isEmpty()) {
181	            // Owners sharing a normalized last name and address form a household with a
182	            // stable shared identifier; backfill any members created before it was formed.
183	            // The household id is part of the identity key, so two members with different
184	            // telephones have different identity keys and are both allowed.
185	            householdId = householdId(lastName, normalizedAddress);
186	            for (Owner member : householdMembers) {
187	                if (!householdId.equals(member.getHouseholdId())) {
188	                    member.setHouseholdId(householdId);
189	                    this.clinicService.saveOwner(member);
190	                }
191	            }
192	        }
193	        String telephone = toE164(ownerFieldsDto.getTelephone());
194	        ownerFieldsDto.setTelephone(telephone);
195	        String email = normalizeEmail(ownerFieldsDto.getEmail());
196	        ownerFieldsDto.setEmail(email);
197	        // Single, consolidated duplicate check: reject only when the new owner's whole
198	        // derived identity key (telephone|email|householdId) equals an existing owner's.
199	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
200	        boolean identityInUse = this.clinicService.findAllOwners().stream()
201	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
202	                existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
203	        if (identityInUse) {
204	            throw new DuplicateIdentityException(
205	                "an owner with the same identity key already exists");
206	        }
207	        HttpHeaders headers = new HttpHeaders();
208	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
209	        owner.setRegistrationDate(registrationDate);
210	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
211	        owner.setHouseholdId(householdId);
212	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
213	        owner.setBulkSignupWarning(bulkSignupWarning);
214	        // Household size after this create: existing members plus the owner being created.
215	        owner.setHouseholdSize(householdMembers.size() + 1);
216	        this.clinicService.saveOwner(owner);
217	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
218	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
219	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
220	            ownerDto.getMembershipLevel());
221	        headers.setLocation(UriComponentsBuilder.newInstance()
222	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
223	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
224	    }
