257	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner == null) {
260	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	        }
262	        HttpHeaders headers = new HttpHeaders();
263	        Pet pet = petMapper.toPet(petFieldsDto);
264	        owner.setId(ownerId);
265	        pet.setOwner(owner);
266	        pet.getType().setName(null);
267	        this.clinicService.savePet(pet);
268	        PetDto petDto = petMapper.toPetDto(pet);
269	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
270	            .buildAndExpand(pet.getId()).toUri());
271	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
272	    }
