276	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
277	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
278	        if (currentOwner != null) {
279	            Pet currentPet = this.clinicService.findPetById(petId);
280	            if (currentPet != null) {
281	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
282	                currentPet.setName(petFieldsDto.getName());
283	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
284	                this.clinicService.savePet(currentPet);
285	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
286	            }
287	        }
288	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	    }
