320	    private static boolean isBlank(String value) {
321	        return value == null || value.isBlank();
322	    }
323	
324	    /**
325	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
326	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
327	     * to the effective registration date (whether supplied in the request or defaulted to the server
328	     * date), so every value derived from the registration date sees the adjusted business day.
329	     */
330	    private static LocalDate toBusinessDay(LocalDate date) {
331	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
332	            date = date.plusDays(1);
333	        }
334	        return date;
335	    }
336	
337	    /**
338	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
339	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
340	     * lower-cased so that last names are compared case-insensitively.
341	     */
342	    private static String normalizeHousehold(String value) {
343	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
344	    }
345	
346	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
347	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
348	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
349	
350	    /**
351	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
352	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
353	     * upper-cased, and common street-type abbreviations are expanded token-by-token
354	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
355	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
356	     * used for every address comparison (household-duplicate detection and the shared household id).
357	     */
358	    private static String normalizeAddress(String value) {
359	        if (value == null) {
360	            return "";
361	        }
362	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
363	        if (collapsed.isEmpty()) {
364	            return "";
365	        }
366	        String[] tokens = collapsed.split(" ");
367	        StringBuilder sb = new StringBuilder();
368	        for (int i = 0; i < tokens.length; i++) {
369	            if (i > 0) {
370	                sb.append(' ');
371	            }
372	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
373	        }
374	        return sb.toString();
375	    }
376	
377	    /**
378	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
379	     * deterministic function of the normalized last name and address, so every owner that
380	     * shares those values maps to the same identifier regardless of creation order.
381	     */
382	    private static String householdId(String normalizedLastName, String normalizedAddress) {
383	        String key = normalizedLastName + "\n" + normalizedAddress;
384	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
385	    }
386	
387	    /**
388	     * Builds the {@code customerCode} assigned to a new owner, formatted
389	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
390	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
391	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
392	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
393	     */
394	    private String nextCustomerCode(String city, String lastName) {
395	        String city3 = prefix3(city);
396	        String last3 = prefix3(lastName);
397	        long sequence = this.clinicService.findAllOwners().stream()
398	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
399	            .count() + 1L;
400	        return String.format("%s-%s-%04d", city3, last3, sequence);
401	    }
402	
403	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
404	    private static String prefix3(String value) {
405	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
406	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
407	    }
408	
409	    /**
410	     * Counts the existing owners that share the given first name and last name, compared
411	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
412	     * owner currently being created is saved), so it reflects how many namesakes preceded the
413	     * new owner.
414	     */
415	    private int countNamesakes(String firstName, String lastName) {
416	        return (int) this.clinicService.findAllOwners().stream()
417	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
418	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
419	            .count();
420	    }
421	
422	    /**
423	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
424	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
425	     * national one, a single leading {@code '0'} is dropped, and the default country code
426	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
427	     * national number must have the length required by its country code ({@code '+61'} requires 9
428	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
429	     * raised (reported to the client as 400).
430	     */
431	    private static String toE164(String telephone) {
432	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
433	        String digits;
434	        if (cleaned.startsWith("+")) {
435	            digits = cleaned.substring(1);
436	        } else {
437	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
438	            digits = "61" + national;
439	        }
440	        if (!digits.matches("[0-9]{8,15}")) {
441	            throw new InvalidTelephoneException(
442	                "telephone must form a valid E.164 number with 8 to 15 digits");
443	        }
444	        validateNationalLength(digits);
445	        return "+" + digits;
446	    }
447	
448	    /** National-number length required for each supported country code (digits after the code). */
449	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
450	        "61", 9, "1", 10);
451	
452	    /**
453	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
454	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
455	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
456	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
457	     */
458	    private static void validateNationalLength(String digits) {
459	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
460	            String code = entry.getKey();
461	            if (digits.startsWith(code)) {
462	                int nationalLength = digits.length() - code.length();
463	                if (nationalLength != entry.getValue()) {
464	                    throw new InvalidTelephoneException(
465	                        "telephone national number must have " + entry.getValue()
466	                            + " digits for country code +" + code);
467	                }
468	                return;
469	            }
470	        }
471	    }
472	
473	    /**
474	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
475	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
476	     * any 4-digit postcode.
477	     */
478	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
479	        "NSW", new int[] {2000, 2099},
480	        "VIC", new int[] {3000, 3099},
481	        "QLD", new int[] {4000, 4099});
482	
483	    /**
484	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
485	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
486	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
487	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
488	     * no known region accepts any 4-digit postcode. A violation raises an
489	     * {@link InvalidPostcodeException} (reported to the client as 400).
490	     */
491	    private static void validatePostcode(String city, String postcode) {
492	        if (isBlank(postcode)) {
493	            return;
494	        }
495	        if (!postcode.matches("[0-9]{4}")) {
496	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
497	        }
498	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.locality(city));
499	        if (range == null) {
500	            return;
501	        }
502	        int value = Integer.parseInt(postcode);
503	        if (value < range[0] || value > range[1]) {
504	            throw new InvalidPostcodeException(
505	                "postcode is out of range for the owner's city region");
506	        }
507	    }
508	
509	    /**
510	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
511	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
512	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
513	     * stored and returned in canonical form.
514	     */
515	    private static String normalizeEmail(String email) {
516	        if (isBlank(email)) {
517	            return null;
518	        }
519	        String trimmed = email.trim();
520	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
521	            throw new InvalidEmailException("email must be a syntactically valid address");
522	        }
