3	/**
4	 * Derives an owner's locality (region) preferring the postcode over the city.
5	 *
6	 * <p>The postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
7	 * QLD 4000-4099); only when the postcode is absent or falls in no known range
8	 * does derivation fall back to the fixed city-to-region table (Sydney -> NSW,
9	 * Melbourne -> VIC, Brisbane -> QLD). This returns the same region for the known
10	 * cities but disambiguates cities that share a name.
11	 *
12	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper})
13	 * so MapStruct does not mistake it for a generic {@code String -> String}
14	 * mapping method and apply it to unrelated fields; the mapper references it only
15	 * through an explicit expression.
16	 */
17	public final class LocalityDeriver {
18	
19	    private LocalityDeriver() {
20	    }
21	
22	    /**
23	     * Returns the canonical region string, preferring the postcode: if the postcode falls in a
24	     * known region's range it wins; otherwise the city-to-region table is used. Returns
25	     * {@code "UNKNOWN"} when neither yields a region.
26	     */
27	    public static String locality(String city, String postcode) {
28	        String byPostcode = regionForPostcode(postcode);
29	        if (byPostcode != null) {
30	            return byPostcode;
31	        }
32	        return locality(city);
33	    }
34	
35	    /**
36	     * Returns the canonical region string for the given city, or {@code "UNKNOWN"}
37	     * when the city is {@code null} or not in the fixed table.
38	     */
39	    public static String locality(String city) {
40	        if (city == null) {
41	            return "UNKNOWN";
42	        }
43	        return switch (city) {
44	            case "Sydney" -> "NSW";
45	            case "Melbourne" -> "VIC";
46	            case "Brisbane" -> "QLD";
47	            default -> "UNKNOWN";
48	        };
49	    }
50	
51	    /**
52	     * Returns the region whose fixed inclusive range contains the given 4-digit postcode
53	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode is
54	     * absent, not a 4-digit value, or in no known range.
55	     */
56	    private static String regionForPostcode(String postcode) {
57	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
58	            return null;
59	        }
60	        int value = Integer.parseInt(postcode);
61	        if (value >= 2000 && value <= 2099) {
62	            return "NSW";
63	        }
64	        if (value >= 3000 && value <= 3099) {
65	            return "VIC";
66	        }
67	        if (value >= 4000 && value <= 4099) {
68	            return "QLD";
69	        }
70	        return null;
71	    }
72	}
