@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
@Override
public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
    List<String> missingFields = new ArrayList<>();
    if (isBlank(ownerFieldsDto.getFirstName())) {
        missingFields.add("firstName");
    }
    if (isBlank(ownerFieldsDto.getLastName())) {
        missingFields.add("lastName");
    }
    String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
    if (isBlank(normalizedAddress)) {
        missingFields.add("address");
    }
    if (isBlank(ownerFieldsDto.getCity())) {
        missingFields.add("city");
    }
    if (isBlank(ownerFieldsDto.getTelephone())) {
        missingFields.add("telephone");
    }
    if (!missingFields.isEmpty()) {
        throw new MissingOwnerFieldsException(missingFields);
    }
    validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
    LocalDate registrationDate = toBusinessDay(
        ownerFieldsDto.getRegistrationDate() != null
            ? ownerFieldsDto.getRegistrationDate()
            : LocalDate.now());
    long registeredOnDay = this.clinicService.findAllOwners().stream()
        .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
        .count();
    if (registeredOnDay >= 100) {
        throw new DailyRegistrationLimitException(
            "100 or more owners have already been registered today");
    }
    boolean bulkSignupWarning = registeredOnDay > 80;
    String city = ownerFieldsDto.getCity();
    long ownersInCity = this.clinicService.findAllOwners().stream()
        .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
        .count();
    if (ownersInCity >= 50) {
        throw new CityAtCapacityException(
            "the owner's city already contains 50 or more owners");
    }
    ownerFieldsDto.setAddress(normalizedAddress);
    String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
    List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
        .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
            && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
        .toList();
    String householdId = null;
    if (!householdMembers.isEmpty()) {
        householdId = householdId(lastName, normalizedAddress);
        for (Owner member : householdMembers) {
            if (!householdId.equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId);
                this.clinicService.saveOwner(member);      // backfills existing members
            }
        }
    }
    String telephone = toE164(ownerFieldsDto.getTelephone());
    ownerFieldsDto.setTelephone(telephone);
    String email = normalizeEmail(ownerFieldsDto.getEmail());
    ownerFieldsDto.setEmail(email);
    String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
    boolean identityInUse = this.clinicService.findAllOwners().stream()
        .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
            existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
    if (identityInUse) {
        throw new DuplicateIdentityException(
            "an owner with the same identity key already exists");
    }
    HttpHeaders headers = new HttpHeaders();
    Owner owner = ownerMapper.toOwner(ownerFieldsDto);
    owner.setRegistrationDate(registrationDate);
    owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
    owner.setHouseholdId(householdId);
    owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
    owner.setBulkSignupWarning(bulkSignupWarning);
    owner.setHouseholdSize(householdMembers.size() + 1);
    this.clinicService.saveOwner(owner);
    OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
    AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
        owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
        ownerDto.getMembershipLevel());
    headers.setLocation(UriComponentsBuilder.newInstance()
        .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
    return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
}
```

### Private helpers used by the create path (same file)
- `isBlank` (320-322): null-or-blank check.
- `toBusinessDay` (330-335): rolls Sat/Sun forward to Monday.
- `normalizeHousehold` (342-344): trim, collapse whitespace, lower-case (used for household comparison).
- `ADDRESS_ABBREVIATIONS` (347-348) + `normalizeAddress` (358-375): trim, collapse whitespace, upper-case, expand `ST→STREET`, `RD→ROAD`, `AVE→AVENUE`. Null/blank → `""`.
- `householdId` (382-385): deterministic `UUID.nameUUIDFromBytes(normalizedLastName + "\n" + normalizedAddress)`.
- `nextCustomerCode` (394-401): `"<CITY3>-<LAST3>-<NNNN>"`, where NNNN = (count of owners already in that city) + 1, zero-padded to 4.
- `prefix3` (404-407): upper-cased first 3 letters (non-letters stripped).
- `countNamesakes` (415-420): count of existing owners with same first+last name (case-insensitive).
- `toE164` (431-446) + `NATIONAL_LENGTH_BY_COUNTRY_CODE` (449-450) + `validateNationalLength` (458-471): telephone normalization to E.164; strips spaces/dashes/brackets; keeps leading `+`, else drops a single leading `0` and prepends `+61`; must be 8-15 digits; `+61` requires 9 national digits, `+1` requires 10; otherwise throws `InvalidTelephoneException`.
- `REGION_POSTCODE_RANGE` (478-481) + `validatePostcode` (491-507): optional postcode; when present must be 4 digits; if the city's region is known (via `LocalityDeriver.locality(city)`) must fall in NSW 2000-2099 / VIC 3000-3099 / QLD 4000-4099; otherwise throws `InvalidPostcodeException`.
- `normalizeEmail` (515-524): optional; blank → `null`; else must match `EMAIL_PATTERN` (else `InvalidEmailException`); returns trimmed, lower-cased.

